[{"order":1,"type":"heading","text":"Mastering Custom Dataset, DataLoader, and Samplers in PyTorch"},{"order":2,"type":"paragraph","text":"When building deep learning models, working with standard datasets like MNIST or CIFAR-10 is straightforward using torchvision. However, real-world machine learning projects require handling custom data formats, custom augmentation pipelines, and specialized batching strategies. PyTorch provides three core abstractions for this purpose: Dataset, DataLoader, and Sampler."},{"order":3,"type":"subheading","text":"1. Creating a Custom Dataset"},{"order":4,"type":"paragraph","text":"The torch.utils.data.Dataset class is an abstract class representing your dataset. To create your own custom dataset, you must inherit from Dataset and implement three essential methods: __init__, __len__, and __getitem__."},{"order":5,"type":"code","text":"import torch
from torch.utils.data import Dataset

class CustomDataset(Dataset):
    def __init__(self, data, labels, transform=None):
        self.data = data
        self.labels = labels
        self.transform = transform

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        sample = self.data[idx]
        label = self.labels[idx]

        if self.transform:
            sample = self.transform(sample)

        return sample, label"},{"order":6,"type":"subheading","text":"2. Utilizing the DataLoader"},{"order":7,"type":"paragraph","text":"While the Dataset retrieves individual samples and their labels one at a time, a machine learning model requires batches of data, often shuffled and loaded in parallel using multiple worker processes. This is handled by torch.utils.data.DataLoader."},{"order":8,"type":"code","text":"from torch.utils.data import DataLoader

# Dummy data generation
features = torch.randn(100, 3, 64, 64)
targets = torch.randint(0, 2, (100,))

dataset = CustomDataset(features, targets)

data_loader = DataLoader(
    dataset=dataset,
    batch_size=16,
    shuffle=True,
    num_workers=2
)

for batch_idx, (data, target) in enumerate(data_loader):
    print(f"Batch {batch_idx}: Data shape {data.shape}, Targets shape {target.shape}")
    break"},{"order":9,"type":"subheading","text":"3. Implementing Custom Samplers"},{"order":10,"type":"paragraph","text":"Samplers define the strategy used to iterate over indices in the dataset. By default, DataLoader uses a RandomSampler when shuffle=True, or a SequentialSampler when shuffle=False. You can create custom samplers by inheriting from torch.utils.data.Sampler to handle imbalanced datasets or implement specialized sampling strategies."},{"order":11,"type":"code","text":"from torch.utils.data import Sampler

class ReverseSampler(Sampler):
    def __init__(self, data_source):
        self.data_source = data_source

    def __iter__(self):
        # Return indices in reverse order
        return iter(range(len(self.data_source) - 1, -1, -1))

    def __len__(self):
        return len(self.data_source)

custom_sampler = ReverseSampler(dataset)

custom_loader = DataLoader(
    dataset=dataset,
    batch_size=16,
    sampler=custom_sampler
)"},{"order":12,"heading":"Summary","type":"bullet_point","text":"Dataset abstracts data storage, lookup, and transformations."},{"order":13,"type":"bullet_point","text":"DataLoader manages batching, shuffling, and multi-process data loading out-of-the-box."},{"order":14,"type":"bullet_point","text":"Samplers give you precise control over index iteration strategies to handle advanced machine learning workflows."}]
